package co.fcv.citas.user;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="users", uniqueConstraints={@UniqueConstraint(name="uk_users_email",columnNames="email"),@UniqueConstraint(name="uk_users_document",columnNames={"document_type","document_number"})})
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String names; @Column(nullable=false) private String surnames; @Column(name="document_type",nullable=false) private String documentType; @Column(name="document_number",nullable=false) private String documentNumber; @Column(nullable=false) private String email; @Column(nullable=false) private String phone; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(nullable=false) private String role="USER"; @Column(nullable=false) private boolean active=true; @Column(nullable=false) private Instant createdAt=Instant.now(); protected User(){} public User(String n,String s,String dt,String dn,String e,String p,String h){names=n;surnames=s;documentType=dt;documentNumber=dn;email=e;phone=p;passwordHash=h;} public Long getId(){return id;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getRole(){return role;} public boolean isActive(){return active;} }
